import { readFile, writeFile } from "node:fs/promises";

// Chrome deduplicates content-script paths across worlds. Give MAIN its own
// entry point while keeping the contract definitions shared with the worker
// and isolated content scripts.
const sources = [
  "contracts/job-urls.js",
  "contracts/messages.js",
  "indeed-description-capture.js",
];
const contents = await Promise.all(sources.map((path) =>
  readFile(new URL(`../extension/${path}`, import.meta.url), "utf8"),
));
await writeFile(
  new URL("../extension/indeed-main.js", import.meta.url),
  "// Generated by npm run build. Edit the source files instead.\n" + contents.join("\n"),
);
